    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        inds = [i for i, x in enumerate(row) if x != bg]
        if inds:
            last = inds[-1]
            for c in range(last + 1, len(row)):
                out[r][c] = 1
    return out
